import {LANDMARKS} from './landmarks.js?v=building-preview-navigation-2';
export function showLandmarks({city,dialog,close,setTool}){const c=city();dialog('Landmarks · a signature skyline',`<p>Choose a landmark for your city. Each is available immediately, once per city, and can be rebuilt after demolition or destruction.</p><div class="landmark-gallery">${Object.entries(LANDMARKS).map(([key,d])=>{const placed=c.tiles.some(t=>t.type===key);return `<article class="milestone"><img src="./assets/${d.asset}" alt="${d.name} gallery illustration" style="width:100%;height:170px;object-fit:contain"><small>${d.place}</small>${d.model?'<p class="fine">Original illustration · City view uses a geometric model that turns with the map.</p>':''}<h3>${d.name}</h3><p>${d.size} × ${d.size} clear, level land · Free placement · No monthly upkeep.</p><button data-landmark="${key}" ${placed?'disabled':''}>${placed?'Already placed':'Place '+d.name}</button></article>`;}).join('')}</div><p>Landmarks give your city a distinctive skyline. Alien craft prefer standing landmarks when selecting targets. They add no jobs or direct income in this reconstruction.</p><p class="fine">First landmark collection. The full original catalog remains unfinished; footprints and costs are reconstruction choices.</p>`);document.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>{setTool(b.dataset.landmark);close();});}
